import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Codex Cloud","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-cloud.md","filePath":"products/ai-coding/codex/codex-cloud.md","lastUpdated":1787107158000}'),n={name:"products/ai-coding/codex/codex-cloud.md"};function s(i,e,d,l,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="codex-cloud" tabindex="-1">Codex Cloud <a class="header-anchor" href="#codex-cloud" aria-label="Permalink to &quot;Codex Cloud&quot;">​</a></h1><blockquote><p>A <strong>tutorial</strong> — run a coding task in an isolated hosted environment, review the diff, then open a PR. Cloud is one Codex surface, not a second product. Sandbox, approval, and <code>AGENTS.md</code> still apply.</p><p>Official landing: <a href="https://learn.chatgpt.com/codex/cloud" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/cloud</a>. Docs: <a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a>. Entry: <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Account</td><td>A ChatGPT plan that includes Codex. Limits live on the <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">pricing page</a></td></tr><tr><td>GitHub</td><td>A GitHub account you can authorize, plus the repos Codex should see</td></tr><tr><td>Browser</td><td><a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a></td></tr><tr><td>Optional CLI</td><td>Installed <a href="./codex-cli.html">Codex CLI</a> for <code>codex cloud</code> / <code>codex cloud exec</code></td></tr></tbody></table><p><strong>Learning objectives</strong>: stand up one Cloud environment; start a task from the web or CLI; review the summary and diff; know when Cloud beats the laptop.</p><p><strong>Non-goals</strong>: local sandbox setup (<a href="./codex-cli.html">CLI</a>); IDE first chat (<a href="./codex-ide.html">IDE</a>); security scans (<a href="./codex-security.html">Security</a>); plan numbers (<a href="./chatgpt-plus.html">Plans</a>).</p><h2 id="what-cloud-is-—-and-is-not" tabindex="-1">What Cloud is — and is not <a class="header-anchor" href="#what-cloud-is-—-and-is-not" aria-label="Permalink to &quot;What Cloud is — and is not&quot;">​</a></h2><p>Cloud runs Codex on OpenAI-hosted machines against a <strong>reproducible environment</strong> you configure per repository. Each task gets its own isolated env. Several tasks can run at once. You review when they finish.</p><p>It is <strong>not</strong>:</p><ul><li>A fourth product. Hosted code review / QA is a Cloud workflow.</li><li>A replacement for the laptop. Local CLI / IDE stay faster for a focused edit.</li><li>ChatGPT Work Cloud. Work Cloud finishes a deck or research job; Codex Cloud writes code and opens a PR.</li></ul><p>Desktop Codex stays in the <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a>. That surface is mapped on the <a href="./codex-ai.html">product line</a> and in <a href="./chatgpt-work.html#work-vs-codex-on-desktop">Work vs Codex</a> — do not look for a second desktop tutorial here.</p><h2 id="when-to-use-cloud" tabindex="-1">When to use Cloud <a class="header-anchor" href="#when-to-use-cloud" aria-label="Permalink to &quot;When to use Cloud&quot;">​</a></h2><p>Official “use Cloud when…” list:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Why Cloud</th></tr></thead><tbody><tr><td>The job should run in the background</td><td>The laptop stays free</td></tr><tr><td>You want several attempts in parallel</td><td><code>--attempts</code> / multiple chats, then pick</td></tr><tr><td>Work starts in <strong>GitHub, Linear, or Slack</strong></td><td>Official integrations dispatch into Cloud</td></tr><tr><td>You are away from the development machine</td><td>Web UI or <code>codex cloud exec</code></td></tr></tbody></table><p>Stay local when you need this machine’s files, a debugger attached to the current process, or a 30-second edit on the file you already have open (<a href="./codex-ide.html">IDE</a>).</p><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><h3 id="_1-open-codex-and-sign-in" tabindex="-1">1. Open Codex and sign in <a class="header-anchor" href="#_1-open-codex-and-sign-in" aria-label="Permalink to &quot;1. Open Codex and sign in&quot;">​</a></h3><p>Go to <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a> and sign in with the same ChatGPT account you use for the CLI.</p><h3 id="_2-connect-github" tabindex="-1">2. Connect GitHub <a class="header-anchor" href="#_2-connect-github" aria-label="Permalink to &quot;2. Connect GitHub&quot;">​</a></h3><p>Authorize GitHub when prompted. Grant only the repositories Codex should see.</p><h3 id="_3-create-an-environment" tabindex="-1">3. Create an environment <a class="header-anchor" href="#_3-create-an-environment" aria-label="Permalink to &quot;3. Create an environment&quot;">​</a></h3><p>Open <a href="https://chatgpt.com/codex/settings/environments" target="_blank" rel="noreferrer">environment settings</a>. Create an environment for the repo. Configure dependencies, tools, environment variables, and secrets the task needs.</p><p>Details: <a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a>. Internet: <a href="https://learn.chatgpt.com/docs/cloud/internet-access" target="_blank" rel="noreferrer">Agent internet access</a>.</p><h3 id="_4-start-a-task" tabindex="-1">4. Start a task <a class="header-anchor" href="#_4-start-a-task" aria-label="Permalink to &quot;4. Start a task&quot;">​</a></h3><p>Back on <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>, pick the environment and describe the <strong>result</strong>, not the vibe:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a failing test for the date parser in packages/core, then make it pass.</span></span>
<span class="line"><span>Do not touch packages/legacy. Open a draft PR when tests are green.</span></span></code></pre></div><p>Watch the logs, or leave it running.</p><h3 id="_5-review-then-merge-on-your-terms" tabindex="-1">5. Review, then merge on your terms <a class="header-anchor" href="#_5-review-then-merge-on-your-terms" aria-label="Permalink to &quot;5. Review, then merge on your terms&quot;">​</a></h3><p>Read the summary and the diff. Ask for a follow-up, or open a pull request when the work is ready. Do not merge on “looks plausible.”</p><h2 id="from-the-cli" tabindex="-1">From the CLI <a class="header-anchor" href="#from-the-cli" aria-label="Permalink to &quot;From the CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                            # browse environments (Ctrl+O reveals IDs)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the migration dry run&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attempts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 1-4 attempts</span></span></code></pre></div><p><code>--attempts</code> is for nondeterministic tasks. Pick the best result; do not average them.</p><h2 id="dispatch-from-github-linear-or-slack" tabindex="-1">Dispatch from GitHub, Linear, or Slack <a class="header-anchor" href="#dispatch-from-github-linear-or-slack" aria-label="Permalink to &quot;Dispatch from GitHub, Linear, or Slack&quot;">​</a></h2><p>Start a Cloud task without leaving the pull request, issue, channel, or thread.</p><table tabindex="0"><thead><tr><th>From</th><th>Official page</th></tr></thead><tbody><tr><td>GitHub</td><td><a href="https://learn.chatgpt.com/docs/third-party/github" target="_blank" rel="noreferrer">Use Codex with GitHub</a></td></tr><tr><td>Linear</td><td><a href="https://learn.chatgpt.com/docs/third-party/linear" target="_blank" rel="noreferrer">Use Codex in Linear</a></td></tr><tr><td>Slack</td><td><a href="https://learn.chatgpt.com/docs/third-party/slack" target="_blank" rel="noreferrer">Use Codex in Slack</a></td></tr></tbody></table><p>The IDE can also hand a long task to Cloud and return you to the same chat: <a href="https://learn.chatgpt.com/docs/cloud#delegate-from-the-ide-extension" target="_blank" rel="noreferrer">delegate from the IDE</a>.</p><h2 id="hosted-review-is-cloud-not-a-fourth-product" tabindex="-1">Hosted review is Cloud, not a fourth product <a class="header-anchor" href="#hosted-review-is-cloud-not-a-fourth-product" aria-label="Permalink to &quot;Hosted review is Cloud, not a fourth product&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>What it does</th></tr></thead><tbody><tr><td>Local <code>/review</code></td><td>Base-branch or uncommitted diff; does not change the tree</td></tr><tr><td>Cloud code review / QA</td><td>Review and QA in the hosted environment. Eligible customers get <strong>GPT-5.6 Sol</strong>; Cloud selects the model</td></tr><tr><td>Codex Security Review</td><td>PR + repo context + threat model. Research preview; see <a href="./codex-security.html">Security</a></td></tr></tbody></table><p>Local <code>/review</code> is a session command. Do not reuse the hosted-review name for it.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Skipping the environment</td><td>Missing deps, failed installs, empty diffs</td><td>Configure the env before the first real task</td></tr><tr><td>Treating Cloud as a second laptop</td><td>Secrets and local-only tools are not there</td><td>Put secrets in the env; keep machine-local work local</td></tr><tr><td>Merging the first plausible PR</td><td>Tests never ran, or ran against the wrong tree</td><td>Read the diff; require the test output</td></tr><tr><td>Confusing Cloud with Work Cloud</td><td>You get a deck instead of a PR</td><td>Switch to <strong>Codex</strong> at <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a></td></tr><tr><td>Expecting Cloud while the laptop sleeps for Remote</td><td>Different products</td><td><a href="./codex-remote.html">Remote</a> drives a <strong>connected computer</strong>; Cloud does not need that machine</td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>A frontend monorepo: three Cloud chats try the same flaky migration with <code>--attempts 3</code>. You keep editing the design-system package in the <a href="./codex-ide.html">IDE</a>. The winning Cloud attempt opens a draft PR. You review it on the phone with <a href="./codex-remote.html">Remote</a> only if the laptop is still the review host — otherwise stay on the web Cloud UI.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Environment knobs → <a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a></li><li>Internet policy → <a href="https://learn.chatgpt.com/docs/cloud/internet-access" target="_blank" rel="noreferrer">Agent internet access</a></li><li>Editor handoff → <a href="./codex-ide.html">IDE</a></li><li>Phone approvals on a <strong>local</strong> host → <a href="./codex-remote.html">Remote</a></li><li>Wiring CI on your runners → <a href="./integration.html">Project Integration</a></li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/cloud" target="_blank" rel="noreferrer">Codex cloud (landing)</a></li><li><a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud (docs)</a></li><li><a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">Cloud environments</a></li><li><a href="https://learn.chatgpt.com/docs/cloud/internet-access" target="_blank" rel="noreferrer">Agent internet access</a></li><li><a href="https://learn.chatgpt.com/docs/third-party/github" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://learn.chatgpt.com/docs/third-party/linear" target="_blank" rel="noreferrer">Linear</a> · <a href="https://learn.chatgpt.com/docs/third-party/slack" target="_blank" rel="noreferrer">Slack</a></li><li><a href="https://learn.chatgpt.com/docs/code-review" target="_blank" rel="noreferrer">Code review</a></li><li><a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a></li></ul>`,47)])])}const k=t(n,[["render",s]]);export{f as __pageData,k as default};
